 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>', back:'<path d="m15 18-6-6 6-6"/>', home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',
 flash:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>', rotate:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 9a7 7 0 0 1 12-2l2 5M4 12l2 5a7 7 0 0 0 12-2"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>', check:'<path d="m4 12 5 5L20 6"/>', plus:'<path d="M12 5v14M5 12h14"/>',
 trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',
